insert into practice_context_blocks (id, exercise_id, label, image_url, text_content, block_type) values
  ('68b85cc7-f3d7-4f3d-b020-2e9d9119c859', '060f504d-cc4d-49be-9fe9-63e3155cbc48', $$bron 1: verslag van Amerigo Vespucci over de bevolking van Brazilië (1503)$$,
   $$geschiedenis-havo-2021-ii-ontdekkers-en-hervormers-bron1.png$$,
   $$bron 1 In 1503 publiceert de ontdekkingsreiziger Amerigo Vespucci een verslag van zijn eerste reis naar Brazilië. Hij schrijft hierin over de oorspronkelijke bevolking:
Iedereen loopt compleet naakt rond, ze bedekken geen enkel deel van hun lichaam en ze lopen tot hun dood net zo bloot rond als ze zijn geboren. Ze hebben grote stevige lichamen, goed gevormd en in proportie en hebben een kleur die een beetje lijkt op rood. (…) Ze zijn mooi om te zien maar ze vernielen zelf hun uiterlijk want ze boren gaten in hun wangen, lippen, neuzen en oren. En denk maar niet dat die gaten klein zijn of dat ze er maar eentje hebben. Sommigen hebben alleen al in hun gezicht zeven gaten, sommige zo groot als een pruim. Ze stoppen hier blauwe steentjes, stukjes marmer, fraaie albasten kristallen, witte botten en andere versieringen in (…). Ze trouwen met zoveel vrouwen als ze maar willen, een zoon woont samen met zijn moeder, een broer met zijn zuster, neven met nichten (…). En krijgsgevangenen worden niet gedood, niet om hun leven te sparen maar om ze later te slachten om op te eten. Ze eten elkaar, de overwinnaars eten de verliezers en net als ander vlees is mensenvlees onderdeel van het dagelijkse voedsel. (…) Ik was zeventwintig dagen in een stad waar ik gezouten mensenvlees zag dat hing aan balken tussen de huizen.$$, 'inline'),
  ('8e49c694-9e10-4650-93f6-5f6cd6204d8b', '2784d1c4-fd4e-46cd-8fc3-7661c07138ee', $$bron 4: prent van een Engelse wever (rond 1800)$$,
   $$geschiedenis-havo-2021-ii-het-britse-rijk-bron4.png$$,
   $$bron 4 Prent van rond 1800 van een Engelse wever:
[Afbeelding] Prent: een man zit in een werkplaats achter een groot houten weefgetouw; op de voorgrond staat een spinnewiel.
Toelichting: De wever zit achter een weefgetouw in zijn werkplaats. Op de voorgrond staat een spinnewiel.$$, 'inline'),
  ('5fc4c186-55b0-4ac2-94b4-305b9676acac', '2784d1c4-fd4e-46cd-8fc3-7661c07138ee', $$bron 5: verhoor van arbeider Samuel Coulson door een regeringscommissie (1833)$$,
   $$geschiedenis-havo-2021-ii-het-britse-rijk-bron5.png$$,
   $$bron 5 In 1833 ondervraagt een Britse regeringscommissie de arbeider Samuel Coulson over zijn kinderen, die werken in een fabriek.
Vraag (van de commissie): Op welke leeftijd gingen uw dochters aan het werk? Antwoord (van Samuel Coulson): De oudste was 12, de middelste 11 en de jongste was 8 jaar toen ze voor het eerst naar de fabriek gingen.
Vraag: Hoe laat vertrokken zij ''s morgens? Antwoord: Tijdens de drukke tijd vertrokken ze om 3 uur in de ochtend, tot 10 uur of half 11 ''s avonds.
Vraag: Hoeveel pauze hadden zij tijdens de 19 uur die zij werkten? Antwoord: Een kwartier om te ontbijten en een half uur voor het avondeten. Ze hadden ook een kwartier drinkpauze.
Vraag: Was het niet heel moeilijk om de kinderen ''s morgens wakker te krijgen? Antwoord: Ja, in het begin moesten we ze oppakken en wakker schudden.
Vraag: Stel dat ze iets te laat op het werk waren, wat was dan de consequentie? Antwoord: In dat geval werd er een kwart van een dagloon ingehouden.$$, 'inline'),
  ('359713df-912c-4fa5-92f6-ee7f578bb4d6', '2784d1c4-fd4e-46cd-8fc3-7661c07138ee', $$bron 6: toespraak van Henry Cole over de wereldtentoonstelling (1849)$$,
   $$geschiedenis-havo-2021-ii-het-britse-rijk-bron6.png$$,
   $$bron 6 Henry Cole is een van de initiatiefnemers van de wereldtentoonstelling in 1851. Twee jaar daarvoor houdt hij een toespraak voor een groep industriëlen in Londen. In een weergave van de toespraak staat:
Het was de vraag of de tentoonstelling beperkt moet zijn tot producten van de Britse industrie. Natuurlijk zou het onjuist zijn om de successen van de machinebouw en wetenschap toe te schrijven aan één land. Het succes van de industriële ontwikkeling komt de hele menselijke beschaving toe. Bovendien kan de Britse industrie er voordeel bij hebben om de eigen producten in een competitie tegenover die van andere landen te plaatsen (gejuich vanuit de zaal). (…) Een andere belangrijke kwestie is de vraag hoe het benodigde geld bij elkaar komt. In andere landen wordt er dan gekeken naar de regering. Maar ik geloof dat wij Britten de meeste zaken veel beter zelf kunnen regelen, dan welke regering ook (goedkeurende geluiden uit de zaal).$$, 'inline'),
  ('50d02869-ebda-436a-b159-8e7e50b0b2d5', '5cb1e834-4d2e-4850-8057-fecd8436cb70', $$bron 2: brief van Elisabeth Charlotte over het hof van Lodewijk XIV (1688)$$,
   $$geschiedenis-havo-2021-ii-regenten-en-vorsten-bron2.png$$,
   $$bron 2 Elisabeth Charlotte is getrouwd met de broer van de Franse koning Lodewijk XIV. In 1688 schrijft ze over Madame de Maintenon, die in het geheim getrouwd is met Lodewijk XIV:
Die oude heks, Maintenon, vindt het leuk om de koning aan te sporen alle leden van de koninklijke familie te haten (…). Alle ministers zitten onder de plak bij deze vrouw en proberen op laaghartige wijze bij haar in de gunst te komen. Alle rechtvaardige en nobele mannen zijn ontevreden maar kunnen niets veranderen aan deze situatie. De jonge mannen [aan het hof] zijn verschrikkelijk gemeen en genieten van het liegen en bedriegen. Zij denken dat het belachelijk is om te proberen een eerlijk mens te zijn.$$, 'inline'),
  ('999c2125-70cb-4e17-b307-98dae4c52d5c', 'f728b552-e62c-4bb7-9872-6615b99f4bfc', $$bron 3: Willem Bosman van de WIC over zijn verblijf in West-Afrika (1703)$$,
   $$geschiedenis-havo-2021-ii-pruiken-en-revoluties-bron3.png$$,
   $$bron 3 Willem Bosman, opperkoopman van de West-Indische Compagnie, schreef in 1703 over zijn verblijf in West-Afrika:
Nu denken in Europa veel mensen, dat de goudmijnen in ons bezit zijn en dat wij (…) slaven voor ons laten werken om het goud naar boven te brengen. Dat denken velen maar het is niet waar. Wij hebben zelf geen toegang tot die mijnen en ik ken ook eigenlijk niemand die ooit zo''n mijn heeft gezien. En daar is dan een goede reden voor: de zwarten zien deze vindplaatsen als een heiligdom en zullen alle mogelijke middelen gebruiken om indringers te weren. [Nadat hij heeft beschreven op welke manier in Afrika goud wordt gedolven, vervolgt hij:] Er bestaat geen enkele twijfel: als dit land aan de Europeanen zou behoren, zouden er veel meer schatten aan de oppervlakte komen, dan nu bij de zwarten het geval is.$$, 'inline'),
  ('96f055a3-0c36-4a7c-99ba-be94cd2505b9', 'f728b552-e62c-4bb7-9872-6615b99f4bfc', $$bron 7: brief van Charles Liernur uit het zuiden van de Verenigde Staten (1862)$$,
   $$geschiedenis-havo-2021-ii-pruiken-en-revoluties-bron7.png$$,
   $$bron 7 Charles Liernur is een Nederlander die in de Verenigde Staten woont. Op 16 januari 1862 schrijft hij in een brief aan zijn ouders in Haarlem:
Wij die in het Zuiden van de Verenigde Staten wonen, weten het natuurlijk beter. Wij weten uit ervaring dat slaven onmisbaar zijn voor het telen van suiker, tabak en katoen, de belangrijkste producten hier. Wij weten dat slavernij niet slecht kan zijn, omdat de zwarten als slaven hier gelukkig en tevreden zijn en genoeg te eten krijgen, (...) terwijl wanneer ze vrij zijn en zich door vrijwillige arbeid moeten onderhouden zij niet genoeg te eten krijgen, ongelukkig worden en sterven.$$, 'inline'),
  ('b4d3d8c5-3ae4-430f-a299-c3eb0f49dc08', '89cbd120-6aae-4022-9971-3ba73b786bcc', $$bron 8: prent 'De Duitse adelaar' van Jan Sluijters in De Nieuwe Amsterdammer (1919)$$,
   $$geschiedenis-havo-2021-ii-duitsland-in-europa-bron8.png$$,
   $$bron 8 Op 28 juni 1919 publiceert het Nederlandse tijdschrift De Nieuwe Amsterdammer deze prent van Jan Sluijters:
[Afbeelding] Prent op de voorpagina van De Nieuwe Amsterdammer: een man trekt een grote, uitgemergelde adelaar de veren uit; de adelaar staat op een stapel papier, op de grond liggen een inktpot en een kanonskogel.
Tekst onder de prent: ''De Duitse adelaar''. ''Clemenceau: Het spijt mij je ook je laatste (v)eer te moeten uittrekken.''
Toelichting: De man is Clemenceau, de premier van Frankrijk. Op het papier staat ''vredesverdrag''. Op de veer staat: ''De eer''.$$, 'inline'),
  ('67657959-ce43-40f6-a2a0-10e3cfbb46d9', '89cbd120-6aae-4022-9971-3ba73b786bcc', $$bron 9: journalist Friedrich Kroner over de inflatie in Berlijn (1923)$$,
   $$geschiedenis-havo-2021-ii-duitsland-in-europa-bron9.png$$,
   $$bron 9 Op 26 augustus 1923 schrijft de journalist Friedrich Kroner over wat hij op straat in Berlijn heeft gezien:
Een epidemie van angst, pure nood: kopers vormen lange rijen (...) voor de winkels, eerst voor één, daarna voor alle winkels. Geen ziekte is zo besmettelijk als deze. De rijen hebben iets suggestiefs: de vluchtige blikken van de vrouwen, de inderhaast aangetrokken keukenschorten, hun afgetobde, geduldige gezichten. Van de rijen gaat steeds hetzelfde signaal uit: de stad (...) zal weer leeggekocht worden. Een pond rijst kostte gisteren 80.000 mark, vandaag 160.000 en morgen misschien wel twee keer zoveel; de dag erna zal de man achter de toonbank zijn schouders ophalen [en zeggen]: "Er is geen rijst meer." "Goed, dan noedels graag." "Ook geen noedels meer." Gerst, gort, bonen, linzen – altijd hetzelfde –, kopen, kopen, kopen. Het stukje papier, het gloednieuwe bankbiljet, nog vochtig van het drukken, uitbetaald als weekloon, verschrompelt onderweg naar de kruidenierswinkel in waarde. De nullen, de vermenigvuldiging van nullen.$$, 'inline'),
  ('bfe8f567-e1b9-4ad3-a7a3-ff62bf7e1da0', '89cbd120-6aae-4022-9971-3ba73b786bcc', $$bron 10: foto van Herman Heukels van Joden die zich moeten melden voor deportatie (Amsterdam, 1943)$$,
   $$geschiedenis-havo-2021-ii-duitsland-in-europa-bron10.png$$,
   $$bron 10 Herman Heukels maakt deze foto op 20 juni 1943 in Amsterdam:
[Afbeelding] Foto: een groep mensen met koffers, tassen en bundels loopt over straat; sommigen dragen een jodenster.
Toelichting: Op de foto zijn Joodse mensen te zien die zich moeten melden voor deportatie.$$, 'inline'),
  ('ae23ec80-d024-4ba1-b214-ef98da2feb0b', '89cbd120-6aae-4022-9971-3ba73b786bcc', $$bron 12: prent van Fritz Behrendt over de DDR in de Frankfurter Allgemeine Zeitung (1989)$$,
   $$geschiedenis-havo-2021-ii-duitsland-in-europa-bron12.png$$,
   $$bron 12 Op 10 juli 1989 publiceert de West-Duitse krant Frankfurter Allgemeine Zeitung deze prent van tekenaar Fritz Behrendt:
[Afbeelding] Prent: een menigte demonstranten met vlaggen en spandoeken trekt voorbij aan een ommuurd bouwwerk met het opschrift ''DDR'', waarop een man zit, omgeven door prikkeldraad.
Toelichting: De man in het midden is DDR-leider Erich Honecker. Op de vlaggen op de achtergrond staat Freiheit (Duits: vrijheid), Glasnost, Perestrojka, Szabadsag (Hongaars: vrijheid), Solidarnosc (Pools: solidariteit), Unabhängigkeit (Duits: onafhankelijkheid) en Demokratie (Duits: democratie).$$, 'inline'),
  ('061623d0-bbcd-473e-915b-02773c969050', 'ca0453ec-9481-495e-9226-2dc44d098d8d', $$bron 11: De Gelderlander over rellen rond de film Rock around the clock (1956)$$,
   $$geschiedenis-havo-2021-ii-nederland-1948-2008-bron11.png$$,
   $$bron 11 Een fragment uit een artikel uit de Nederlandse krant De Gelderlander van
22 oktober 1956 over de Amerikaanse film Rock around the clock:
Zowel in Apeldoorn als in Leeuwarden is het tijdens ''t voorbije weekend tot ernstige relletjes gekomen rond de film Rock around the clock. In Apeldoorn hield een aantal opgeschoten jongens zaterdag- en zondagavond een protestdemonstratie tegen het verbod van de burgemeester om de film te vertonen, waarbij zich later, toen de politie zich met het geval bemoeide, honderden anderen aansloten. In Leeuwarden maakten enkele tientallen hysterische vlegels het vrijdag- en zaterdagavond zo bont dat de burgemeester van die plaats de verdere vertoning van de film heeft verboden.$$, 'inline');

insert into practice_questions (id, exercise_id, question_number, topics, keywords, question_summary, question_image_url, question_text, context_block_ids) values
  ('23f8151e-922e-4fa5-9f12-10d554b3a518', '35e17c11-c966-4a83-8645-a713b0be9cff', 1,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Regenten en vorsten — overig (1600-1700)"}, {"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["chronologie", "ontdekkingsreizen", "Gouden Eeuw", "Amerikaanse Revolutie", "industrialisatie", "dekolonisatie"]'::jsonb,
   $$Chronologisch ordenen van zes besluiten over stadsplanning uit verschillende tijdvakken.$$,
   $$geschiedenis-havo-2021-ii-door-de-tijd-heen-vraag1.png$$, $$Deze besluiten over de stadsplanning van de volgende steden staan in willekeurige volgorde:
1 Amsterdam werd tijdens de economische bloei van de Republiek vier keer zo groot door de aanleg van de grachtengordel.
2 De Spaanse veroveraars van het pas door hen ontdekte Amerika bouwden Mexico-Stad op de ruïnes van de Azteekse hoofdstad Tenochtitlan.
3 Jakarta groeide als hoofdstad van het onafhankelijk geworden Indonesië in enkele jaren uit tot een miljoenenstad, waarbij oude stadsbuurten werden afgebroken om plaats te maken voor flats.
4 George Washington, de eerste president van de Verenigde Staten, liet Washington ontwerpen als hoofdstad van de onafhankelijke Verenigde Staten.
5 In Enschede werden grote arbeiderswijken gebouwd om de arbeiders te huisvesten die naar de stad trokken om te werken in de nieuwe fabrieken.
6 Rome werd uitgebreid met de nieuwe stadswijk EUR in opdracht van de Italiaanse fascistische dictator Mussolini. 2p 1 Zet deze besluiten over stadsplanning in de juiste chronologische volgorde, van vroeger naar later. Noteer alleen de nummers.$$, array[]::uuid[]),
  ('599f8938-36a5-409a-a8d3-3cea5da759c2', '35e17c11-c966-4a83-8645-a713b0be9cff', 16,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Duitsland en de Koude Oorlog (1945-1961)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Hereniging en Europese integratie (1961-1991)"}]'::jsonb,
   '["chronologie", "nationaalsocialisme", "DDR", "opstand 1953", "Berlijnse Muur", "Duitse hereniging"]'::jsonb,
   $$Chronologisch ordenen van zes gebeurtenissen rond een kantoorgebouw in Berlijn in de twintigste eeuw.$$,
   $$geschiedenis-havo-2021-ii-door-de-tijd-heen-vraag16.png$$, $$De volgende gegevens over een kantoorgebouw in Berlijn in de twintigste eeuw staan in willekeurige volgorde:
1 De Deutsche Volksrat riep zichzelf in het gebouw uit tot ''voorlopig parlement'' van de op te richten DDR.
2 De Treuhandanstalt, de organisatie die Oost-Duitse staatsbedrijven moest gaan privatiseren, werd gevestigd in het gebouw.
3 Direct naast het gebouw werd begonnen met de bouw van de Berlijnse Muur.
4 Drie jaar na de machtsovername van de nazi''s werd het ministerie van Rijksluchtvaart gevestigd in het gebouw.
5 Het gebouw bleef tijdens de geallieerde bombardementen op Berlijn grotendeels gespaard.
6 Tijdens de mislukte arbeidersopstand die leidde tot strengere controle door de Staatssicherheitsdienst was het gebouw, waarin verschillende Oost-Duitse ministeries gevestigd waren, doelwit van demonstranten. 2p 16 Zet deze gebeurtenissen in de juiste chronologische volgorde, van vroeger naar later. Noteer alleen de nummers.$$, array[]::uuid[]),
  ('88d39f9c-71e3-4cb0-a7b3-4d934d664cb3', '060f504d-cc4d-49be-9fe9-63e3155cbc48', 2,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["ontdekkingsreizen", "kolonisatie", "Brazilië", "rechtvaardiging", "beeldvorming", "Europese expansie"]'::jsonb,
   $$Uitleggen welke rechtvaardiging voor de kolonisatie van Brazilië de Portugese koning aan het verslag van Vespucci kon ontlenen.$$,
   $$geschiedenis-havo-2021-ii-ontdekkers-en-hervormers-vraag2.png$$, $$Gebruik bron 1. De Portugese koning João III besluit in de zestiende eeuw Brazilië te koloniseren. 2p 2 Leg uit welke rechtvaardiging João III met dit verslag van Vespucci kan geven voor de kolonisatie van Brazilië, waarbij je je antwoord ondersteunt met een verwijzing naar de bron.$$, array['68b85cc7-f3d7-4f3d-b020-2e9d9119c859']::uuid[]),
  ('03a4935d-2a0c-45d3-9c52-221d87c6fa26', '060f504d-cc4d-49be-9fe9-63e3155cbc48', 4,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Ontdekkers en hervormers — overig (1500-1600)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Regenten en vorsten — overig (1600-1700)"}]'::jsonb,
   '["Opstand", "Tachtigjarige Oorlog", "Republiek", "wetenschappelijke revolutie", "waterbouw", "kenmerkend aspect"]'::jsonb,
   $$Met kenmerkende aspecten van de zestiende en zeventiende eeuw de bouw en de aanpak van de citadel van Den Bosch verklaren.$$,
   $$geschiedenis-havo-2021-ii-ontdekkers-en-hervormers-vraag4.png$$, $$Een anekdote: De Engelsman John Evelyn schreef in september 1641 in zijn dagboek over de bouw van de citadel bij de Nederlandse stad Den Bosch. Met deze citadel werd de verdediging van de stad verbeterd. Evelyn noemde de Nederlanders de grootste experts van heel Europa op het gebied van pompen, omdat hij zag dat het land rondom de stad watervrij werd gemaakt met behulp van watermolens en pompen met een slakkenhuis- constructie. 2p 4 Licht deze anekdote toe door:
− met een kenmerkend aspect van de zestiende eeuw de noodzaak voor de bouw van de citadel te verklaren en
− met een kenmerkend aspect van de zeventiende eeuw de beschreven aanpak in Den Bosch te verklaren.$$, array[]::uuid[]),
  ('63e1a82b-f9ac-4cbe-bd5a-6a6b3d76eb56', '2784d1c4-fd4e-46cd-8fc3-7661c07138ee', 3,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["Engelse koloniën", "Noord-Amerika", "Elizabeth I", "Spanje", "kolonisatie", "propaganda"]'::jsonb,
   $$Uitleggen waarom kolonisatie van Noord-Amerika paste in de buitenlandse politiek van Elizabeth I en waarom de prenten van White werden verspreid.$$,
   $$geschiedenis-havo-2021-ii-het-britse-rijk-vraag3.png$$, $$Twee gegevens:
1 De ontdekkingsreiziger Walter Raleigh organiseerde in 1585 een expeditie naar Noord-Amerika nadat de Engelse koningin Elizabeth I opdracht had gegeven om de mogelijkheden voor Engelse kolonisatie te onderzoeken.
2 Walter Raleigh stuurde de tekenaar John White mee met de expeditie om ''naar het leven de natuurlijke bronnen en inwoners te tekenen''. White tekende vissen, planten en dieren en de inheemse Amerikaanse bevolking die kookte en maïs verbouwde. De tekeningen werden gekopieerd en verspreid in Engeland. 3p 3 Licht beide gegevens toe door:
− aan te geven waardoor kolonisatie van juist Noord-Amerika paste in het buitenlandse politieke beleid van Elizabeth I
− uit te leggen dat de verspreiding van de prenten van White de opdracht van Walter Raleigh moest ondersteunen.$$, array[]::uuid[]),
  ('7106e409-9fc9-4129-bfc0-a500d0218893', '2784d1c4-fd4e-46cd-8fc3-7661c07138ee', 7,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["industriële revolutie", "huisnijverheid", "textielnijverheid", "landbouwrevolutie", "bevolkingsgroei", "illustratie"]'::jsonb,
   $$Uitleggen waarom een prent van een thuiswever de beginperiode van de industriële revolutie illustreert en hoe landbouwverbeteringen de industrialisatie mogelijk maakten.$$,
   $$geschiedenis-havo-2021-ii-het-britse-rijk-vraag7.png$$, $$Gebruik bron 4. Stel: Je schrijft een werkstuk over de textielproductie in Groot- Brittannië, een van de nijverheidstakken die als eerste industrialiseert. Je vindt deze prent en besluit om hem te gebruiken als illustratie van de beginperiode van de industriële revolutie. 4p 7 Leg uit:
− met een verwijzing naar de prent waardoor deze geschikt is als illustratie van de beginperiode van de industriële revolutie en
− zonder bron dat de industrialisatie van juist de textielnijverheid mede noodzakelijk wordt door verbeteringen in de Britse landbouw.$$, array['8e49c694-9e10-4650-93f6-5f6cd6204d8b']::uuid[]),
  ('323f073f-05b8-45d3-83da-12ae05ee912f', '2784d1c4-fd4e-46cd-8fc3-7661c07138ee', 8,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["kinderarbeid", "Factory Acts", "sociale kwestie", "fabrieksarbeid", "arbeidsomstandigheden", "1833"]'::jsonb,
   $$Uitleggen waarom een regeringscommissie arbeiders als Coulson verhoorde en welke wet dankzij haar aanbevelingen werd aangenomen.$$,
   $$geschiedenis-havo-2021-ii-het-britse-rijk-vraag8.png$$, $$Gebruik bron 5. De Britse regering wil de arbeidsomstandigheden in Groot-Brittannië verbeteren en laat de commissie hiervoor aanbevelingen doen. 2p 8 Licht dit toe door:
− te verklaren dat de commissie juist mensen als Coulson wil verhoren en
− aan te geven welke wet mede dankzij de aanbevelingen van deze commissie wordt aangenomen.$$, array['5fc4c186-55b0-4ac2-94b4-305b9676acac']::uuid[]),
  ('4ec65b5f-4cd6-4269-b151-f04eecb6493d', '2784d1c4-fd4e-46cd-8fc3-7661c07138ee', 9,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["betrouwbaarheid", "kinderarbeid", "Factory Acts", "regeringscommissie", "sociale kwestie", "bronkritiek"]'::jsonb,
   $$De betrouwbaarheid van een verhoor door een regeringscommissie over kinderarbeid beoordelen en onderbouwen met de bron.$$,
   $$geschiedenis-havo-2021-ii-het-britse-rijk-vraag9.png$$, $$Gebruik bron 5. De commissie moet het voornemen van de Britse regering ondersteunen om de arbeidsomstandigheden te verbeteren. Je twijfelt hierdoor aan de betrouwbaarheid van het interview voor een onderzoek naar kinderarbeid in Groot-Brittannië in de negentiende eeuw. 2p 9 Verklaar je twijfel en ondersteun deze met een voorbeeld uit de bron.$$, array['5fc4c186-55b0-4ac2-94b4-305b9676acac']::uuid[]),
  ('a18e23d1-27ac-41e6-b77a-73852f589faa', '2784d1c4-fd4e-46cd-8fc3-7661c07138ee', 10,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["Wereldtentoonstelling", "liberalisme", "superioriteitsgevoel", "vrije markt", "industriële revolutie", "bron analyseren"]'::jsonb,
   $$Met verwijzingen naar een toespraak van Henry Cole uitleggen hoe hij het Britse superioriteitsgevoel en een liberaal standpunt gebruikt.$$,
   $$geschiedenis-havo-2021-ii-het-britse-rijk-vraag10.png$$, $$Gebruik bron 6. Je concludeert dat Cole het benodigde geld voor de tentoonstelling bij elkaar wil krijgen door gebruik te maken van:
1 het Britse superioriteitsgevoel
2 een liberaal standpunt. 4p 10 Leg beide conclusies uit, waarbij je je antwoord telkens ondersteunt met een andere verwijzing naar de bron.$$, array['359713df-912c-4fa5-92f6-ee7f578bb4d6']::uuid[]),
  ('fa71c140-b0b1-4729-acf1-f68f60f29d6f', '2784d1c4-fd4e-46cd-8fc3-7661c07138ee', 13,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "India als belangrijkste kolonie (1765-1885)"}]'::jsonb,
   '["Indian National Congress", "1885", "Indiaas nationalisme", "emancipatie", "koloniaal bestuur", "keerpunt"]'::jsonb,
   $$Met een gebeurtenis uit 1885 onderbouwen dat dit jaar een keerpunt was in de Britse koloniale overheersing van India.$$,
   $$geschiedenis-havo-2021-ii-het-britse-rijk-vraag13.png$$, $$Volgens sommige historici was 1885 een keerpunt in de geschiedenis van de Britse koloniale overheersing van India. 2p 13 Ondersteun deze bewering door met een gebeurtenis uit 1885 uit te leggen wat er veranderde voor de Britse koloniale machthebbers in India.$$, array[]::uuid[]),
  ('d8d48ac2-3baa-4ceb-9ce7-f612afcf9fcd', '5cb1e834-4d2e-4850-8057-fecd8436cb70', 5,
   '[{"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Regenten en vorsten — overig (1600-1700)"}]'::jsonb,
   '["absolutisme", "Lodewijk XIV", "hofleven", "betrouwbaarheid", "persoonlijk motief", "verklaren"]'::jsonb,
   $$Een negatieve beschrijving van het hof van Lodewijk XIV verklaren vanuit het absolutisme en een persoonlijk motief, en de betrouwbaarheid beoordelen.$$,
   $$geschiedenis-havo-2021-ii-regenten-en-vorsten-vraag5.png$$, $$Gebruik bron 2. Elisabeth Charlotte geeft een negatieve beschrijving van het hofleven onder Madame de Maintenon. Historici beweren dat deze negatieve beschrijving kan worden verklaard vanuit:
1 het absolute karakter van het bewind van Lodewijk XIV en
2 een persoonlijk motief van Elisabeth Charlotte. 4p 5 Ondersteun beide verklaringen met een argument en leg daarna uit dat je door de tweede verklaring twijfelt aan de betrouwbaarheid van deze beschrijving.$$, array['50d02869-ebda-436a-b159-8e7e50b0b2d5']::uuid[]),
  ('a60455c8-d8ed-4577-bb64-00a71b7a03d9', 'f728b552-e62c-4bb7-9872-6615b99f4bfc', 6,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["WIC", "trans-Atlantische slavenhandel", "plantagekoloniën", "goudkust", "koerswijziging", "kenmerkend aspect"]'::jsonb,
   $$Met een kenmerkend aspect van de achttiende eeuw uitleggen welke koerswijziging in het WIC-beleid Willem Bosman voorstelt.$$,
   $$geschiedenis-havo-2021-ii-pruiken-en-revoluties-vraag6.png$$, $$Gebruik bron 3. Uit deze brief kun je afleiden dat Willem Bosman voorstander is van een koerswijziging in het beleid van de West-Indische Compagnie. 3p 6 Toon dit aan door:
− zonder bron met een kenmerkend aspect van de achttiende eeuw aan te geven op welke handel op dat moment de nadruk ligt en met bron uit te leggen welke koerswijziging Bosman voorstelt.$$, array['999c2125-70cb-4e17-b307-98dae4c52d5c']::uuid[]),
  ('56134d5f-ea0b-4d88-aabf-7ce7ad353399', 'f728b552-e62c-4bb7-9872-6615b99f4bfc', 11,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "De Engelse koloniën in de Amerika's (1585-1833)"}]'::jsonb,
   '["abolitionisme", "slavernij", "eenzijdigheid", "natuurrechten", "Verlichting", "Amerikaanse Burgeroorlog"]'::jsonb,
   $$Uitleggen welk eenzijdig beeld van de slavernij een brief uit 1862 geeft en een ideologisch argument van abolitionisten ertegen geven.$$,
   $$geschiedenis-havo-2021-ii-pruiken-en-revoluties-vraag11.png$$, $$Gebruik bron 7. Als abolitionisten in de negentiende eeuw deze brief hadden gelezen, hadden zij de inhoud sterk afgekeurd. 3p 11 Ondersteun dit door:
− uit te leggen welk eenzijdig beeld Liernur geeft van slavernij, waarbij je je antwoord ondersteunt met een verwijzing naar de bron en
− een ideologisch argument van abolitionisten tegen zijn standpunt te geven.$$, array['96f055a3-0c36-4a7c-99ba-be94cd2505b9']::uuid[]),
  ('5bccd61d-0cad-4e52-91c1-20e686d3273b', 'a67fd33e-25d7-4999-8e9d-036e00ede948', 12,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}, {"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["industrialisatie", "sociale kwestie", "arbeiderswoningen", "economische wereldcrisis", "tuindorp", "kenmerkend aspect"]'::jsonb,
   $$De bouw van twee Nederlandse tuindorpen (1867 en jaren 1930) verklaren met twee verschillende kenmerkende aspecten.$$,
   $$geschiedenis-havo-2021-ii-burgers-en-stoommachines-vraag12.png$$, $$Twee gegevens over de bouw van ''tuindorpen'' in Nederland:
1 De Hengelose wijk Tuindorp ''t Lansink werd gebouwd nadat in 1867 fabriekseigenaar Charles Stork de opdracht gaf om een wijk te bouwen met moderne arbeiderswoningen in een groene omgeving.
2 De Utrechtse wijk Tuindorp werd gebouwd in de jaren 1930, nadat bleek dat particulieren liever geen aandelen meer kochten en andere mogelijkheden zochten om hun vermogen te beleggen. 2p 12 Verklaar het besluit voor de bouw van beide wijken, ieder vanuit een passend kenmerkend aspect uit moderne tijd. Let op: je mag een kenmerkend aspect maar één keer gebruiken.$$, array[]::uuid[]),
  ('7dcaf1da-468a-4465-b258-304086d2cddf', 'a67fd33e-25d7-4999-8e9d-036e00ede948', 14,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["socialisme", "democratisering", "kiesrecht", "sociale kwestie", "onderwijs", "politieke stroming"]'::jsonb,
   $$Met een kenmerkend aspect de verkiezing van een socialistisch gemeenteraadslid in 1889 verklaren en het verband met zijn onderwijsvoorstel uitleggen.$$,
   $$geschiedenis-havo-2021-ii-burgers-en-stoommachines-vraag14.png$$, $$Poppe de Rook was in 1889 een van de eerste socialisten die in Nederland werd verkozen als gemeenteraadslid. In de gemeenteraad van Lemsterland (Friesland) stelde hij voor om het schoolgeld te halveren voor leerlingen die naar de mulo (meer uitgebreid lager onderwijs) wilden. Uit de verkiezing van Poppe de Rook blijkt dat de politiek in Nederland veranderde. 4p 14 Licht deze verandering toe door:
− een hierbij passend kenmerkend aspect uit de negentiende eeuw te noemen en daarmee de verkiezing van Poppe de Rook als gemeenteraadslid te verklaren en
− uit te leggen wat het verband is tussen de politieke opvatting van Poppe de Rook en zijn voorstel om het schoolgeld voor de mulo te halveren.$$, array[]::uuid[]),
  ('8ef9faa3-4247-48a9-b63f-c322a0632aac', 'a67fd33e-25d7-4999-8e9d-036e00ede948', 15,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}]'::jsonb,
   '["feminisme", "eerste feministische golf", "vrouwenemancipatie", "rolpatroon", "wetenschap", "redeneren"]'::jsonb,
   $$Beredeneren welke kritiek feministen in 1904 zouden hebben op een recensie van het proefschrift van een vrouwelijke historica.$$,
   $$geschiedenis-havo-2021-ii-burgers-en-stoommachines-vraag15.png$$, $$Een anekdote: In 1904 promoveerde de historica Florence Baudet op het proefschrift De maaltijd en de keuken in de Middeleeuwen. Een recensent in het tijdschrift De Amsterdammer schreef hierover: "Waarlijk een aardig idee voor een meisje om een wetenschappelijke opleiding te besluiten met een proefschrift over de ''keuken'' en zo in haar geleerdheid zich aangetrokken te voelen tot het huismoederlijke terrein". 2p 15 Beredeneer welke kritiek feministen zouden hebben op de redenering van deze recensent.$$, array[]::uuid[]),
  ('d58f981a-8121-498b-ba32-97e7f6acca53', 'a67fd33e-25d7-4999-8e9d-036e00ede948', 27,
   '[{"domain": "Het Britse Rijk (1585-1900)", "subdomain": "Koloniën en sociaal-economische ontwikkeling in Groot-Brittannië (1750-1900)"}, {"domain": "Tijdvakken (overige kenmerkende aspecten)", "subdomain": "Wereldoorlogen — overig (1900-1950)"}, {"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1978-2008)"}]'::jsonb,
   '["VOC", "imperialisme", "Tweede Wereldoorlog", "Indonesisch nationalisme", "multiculturele samenleving", "beeldvorming"]'::jsonb,
   $$Uitleggen welke boodschap over de eigen tijd verwijzingen naar Jan Pieterszoon Coen in verschillende periodes overbrachten, ondersteund met kenmerkende aspecten.$$,
   $$geschiedenis-havo-2021-ii-burgers-en-stoommachines-vraag27.png$$, $$Jan Pieterszoon Coen (1587-1629) was gouverneur-generaal van de handelscompagnie VOC, waarvoor hij delen van Indië (het huidige Indonesië) gewelddadig onderwierp. Er werd in latere eeuwen naar hem verwezen:
1 In 1893 onthulde de politicus Herman Schaepman een standbeeld van Coen, waarbij hij Coen "een groot man en een Nederlandse held" noemde.
2 Op 14 mei 1940, vier dagen na de Duitse inval in Nederland, sprak koningin Wilhelmina tot de Nederlandse bevolking, waarbij zij haar rede eindigde met de woorden "Dispereert niet" (wanhoop niet), de lijfspreuk van Coen.
3 In 1943 vernietigden Indonesische nationalisten in opdracht van de Japanse bezetter van Nederlands-Indië een standbeeld van Coen in de stad Batavia.
4 In 1987 protesteerden Molukse Nederlanders, afkomstig uit de voormalige kolonie Nederlands-Indië, tegen de opening van de tentoonstelling Coen, de daden en dagen in dienst van de VOC. Door de tijd heen werd Coen gebruikt om een boodschap over te brengen over de eigen tijd. 4p 27 Toon dit aan door voor twee van de verwijzingen naar Coen uit te leggen welke boodschap over de eigen tijd wordt weergegeven, waarbij je het antwoord telkens ondersteunt met een kenmerkend aspect dat bij de boodschap past. Let op: je mag een kenmerkend aspect maar één keer gebruiken.$$, array[]::uuid[]),
  ('1b2713f8-9a11-4965-86a8-3b39b6ceb82a', '89cbd120-6aae-4022-9971-3ba73b786bcc', 17,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["Verdrag van Versailles", "herstelbetalingen", "Clemenceau", "spotprent", "standpunt", "1919"]'::jsonb,
   $$Met verwijzingen naar een spotprent uitleggen welke mening de tekenaar heeft over het doel van Clemenceau en de gevolgen van Versailles voor Duitsland.$$,
   $$geschiedenis-havo-2021-ii-duitsland-in-europa-vraag17.png$$, $$Gebruik bron 8. De Franse premier Clemenceau eist dat er strenge voorwaarden voor Duitsland worden vastgelegd in het Verdrag van Versailles. 4p 17 Leg uit, telkens met een verschillende verwijzing naar de bron, welke mening Jan Sluijters weergeeft:
− over het doel van Clemenceau en
− over het gevolg hiervan voor Duitsland.$$, array['b4d3d8c5-3ae4-430f-a299-c3eb0f49dc08']::uuid[]),
  ('11a077bd-46bf-4ea5-acf2-9247ca5bf03d', '89cbd120-6aae-4022-9971-3ba73b786bcc', 18,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["Republiek van Weimar", "hyperinflatie", "herstelbetalingen", "politieke instabiliteit", "Dawesplan", "illustratie"]'::jsonb,
   $$Met een ooggetuigenverslag uit 1923 de moeizame start van de Republiek van Weimar illustreren en verklaren.$$,
   $$geschiedenis-havo-2021-ii-duitsland-in-europa-vraag18.png$$, $$Gebruik bron 9. Met deze beschrijving van Friedrich Kroner kun je de moeizame start van de Republiek van Weimar illustreren. 3p 18 Licht dit toe door:
− aan te geven welk aspect van de moeizame start uit de bron naar voren komt en
− zonder bron aan te geven op welke wijze dit bijdroeg aan de politieke instabiliteit in de Republiek en
− zonder bron aan te geven waardoor er een einde kwam aan deze moeilijkheden.$$, array['67657959-ce43-40f6-a2a0-10e3cfbb46d9']::uuid[]),
  ('69a89715-d6a5-4845-9545-9fbf5f922dfb', '89cbd120-6aae-4022-9971-3ba73b786bcc', 19,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Opkomst nationaalsocialisme en gevolgen (1918-1945)"}]'::jsonb,
   '["Duitse bezetting", "Jodenvervolging", "deportatie", "propaganda", "SS", "Holocaust"]'::jsonb,
   $$Het verschil in publicatie van foto's van Jodenvervolging verklaren vanuit de boodschap van de bezetter en het publicatieverbod.$$,
   $$geschiedenis-havo-2021-ii-duitsland-in-europa-vraag19.png$$, $$Gebruik bron 10. De Duitse bezetter betaalt fotograaf Herman Heukels om foto''s te maken. Twee gegevens:
1 Een deel van de foto''s wordt gepubliceerd in de Storm SS, het weekblad van de Nederlandse Schutzstaffel (een nationaalsocialistische paramilitaire organisatie).
2 De foto''s worden niet gepubliceerd in de Nederlandse landelijke dagbladen, die vanaf 1940 geen foto''s van Joden mogen publiceren. 3p 19 Verklaar het verschil in publicatie door:
− met een verwijzing naar de bron uit te leggen welke boodschap de foto''s in de Storm SS moeten uitdragen en
− zonder bron aan te geven wat de Duitse bezetter wil bereiken met het publicatieverbod van foto''s van Joden in de landelijke dagbladen.$$, array['bfe8f567-e1b9-4ad3-a7a3-ff62bf7e1da0']::uuid[]),
  ('3f16bcf7-e2b5-4bce-93b9-d671fe7111b5', '89cbd120-6aae-4022-9971-3ba73b786bcc', 24,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Hereniging en Europese integratie (1961-1991)"}]'::jsonb,
   '["Ostpolitik", "Willy Brandt", "detente", "Koude Oorlog", "BRD", "DDR"]'::jsonb,
   $$Uitleggen dat de Ostpolitik van Willy Brandt paste bij de fase waarin de Koude Oorlog zich bevond.$$,
   $$geschiedenis-havo-2021-ii-duitsland-in-europa-vraag24.png$$, $$De Ostpolitik van Willy Brandt paste bij de fase waarin de Koude Oorlog zich op dat moment bevond. 2p 24 Leg dit uit.$$, array[]::uuid[]),
  ('370be05d-84af-4550-b5f1-afb4834d9f0f', '89cbd120-6aae-4022-9971-3ba73b786bcc', 26,
   '[{"domain": "Duitsland in Europa (1918-1991)", "subdomain": "Hereniging en Europese integratie (1961-1991)"}]'::jsonb,
   '["DDR", "Honecker", "Gorbatsjov", "glasnost en perestrojka", "val van de Muur", "spotprent"]'::jsonb,
   $$Met verwijzingen naar een prent uit 1989 uitleggen welke mening de tekenaar heeft over de DDR-leiding en welke voorspelling hij doet.$$,
   $$geschiedenis-havo-2021-ii-duitsland-in-europa-vraag26.png$$, $$Gebruik bron 12. Deze prent gaat over de situatie in de DDR in 1989. 4p 26 Leg uit, telkens met een verwijzing naar de bron:
− welke mening over de politieke koers van de DDR-leiding de tekenaar weergeeft en
− welke voorspelling over de toekomst van de DDR de tekenaar weergeeft.$$, array['ae23ec80-d024-4ba1-b214-ef98da2feb0b']::uuid[]),
  ('b4497513-12f6-44b2-a447-026f9dceeb4c', 'ca0453ec-9481-495e-9226-2dc44d098d8d', 20,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["verzuiling", "wederopbouw", "consumptiemaatschappij", "jongerencultuur", "rolverdeling", "ordenen"]'::jsonb,
   $$Gegevens over artikelen in het vrouwenblad Beatrijs koppelen aan ontwikkelingen in Nederland na 1945.$$,
   $$geschiedenis-havo-2021-ii-nederland-1948-2008-vraag20.png$$, $$Het tijdschrift Beatrijs was een weekblad voor vrouwen dat werd uitgegeven van 1939 tot 1967. Enkele gegevens over artikelen in het tijdschrift:
1 In de naoorlogse jaren verscheen er in het tijdschrift wekelijks een column van een katholieke priester en was er controle op de inhoud door een katholieke geestelijke.
2 Vanaf de jaren 1950 plaatste het tijdschrift artikelen over wintersport en vliegvakanties.
3 In 1963 werd in het artikel ''Vrouw moet vrouw blijven'' benadrukt dat de vrouw niet buitenshuis zou moeten werken.
4 In 1965 verscheen in het tijdschrift een artikel over de ''ideale schoonzoon'', met daarbij twee foto''s: een van een jongeman in leren jack op een brommer en een van een jongeman in pak. Deze gegevens passen bij ontwikkelingen uit de tweede helft van de twintigste eeuw in Nederland. Hieronder staan vijf ontwikkelingen, in willekeurige volgorde: a de opkomst van een consumptiemaatschappij b de wederopbouw na de Tweede Wereldoorlog c het behoud van de traditionele rolverdeling tussen man en vrouw d het ontstaan van jongerenculturen e het voortbestaan van verzuilde verhoudingen 2p 20 Geef per gegeven aan welke ontwikkeling daarbij hoort. Noteer alleen het cijfer en de daarbij passende letter. Let op: er blijft één ontwikkeling over.$$, array[]::uuid[]),
  ('0bf77d68-690b-4810-b30f-8ac49768bd35', 'ca0453ec-9481-495e-9226-2dc44d098d8d', 21,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["wederopbouw", "Koude Oorlog", "West-Duitsland", "NAVO", "economisch belang", "buitenlandse politiek"]'::jsonb,
   $$Uitleggen hoe Nederland profiteerde van de West-Duitse wederopbouw en herbewapening begin jaren 1950.$$,
   $$geschiedenis-havo-2021-ii-nederland-1948-2008-vraag21.png$$, $$Ondanks sterke anti-Duitse gevoelens in de Nederlandse samenleving, steunde de Nederlandse overheid de wederopbouw van West-Duitsland en pleitte zij begin jaren 1950 voor de West-Duitse herbewapening. Historici concluderen dat de Nederlandse overheid beide ontwikkelingen steunde omdat Nederland hiervan zou profiteren. 2p 21 Ondersteun deze conclusie door voor beide ontwikkelingen aan te geven op welke manier Nederland hiervan kon profiteren.$$, array[]::uuid[]),
  ('4ae7bd92-7bb4-4785-9c73-25b5ff20790a', 'ca0453ec-9481-495e-9226-2dc44d098d8d', 22,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["jongerencultuur", "nozems", "rock-'n-roll", "verzuiling", "eenzijdigheid", "maatschappelijke verandering"]'::jsonb,
   $$Uitleggen waaruit de eenzijdigheid van een krantenartikel over rellen rond Rock around the clock blijkt en met welke verandering de krant moeite heeft.$$,
   $$geschiedenis-havo-2021-ii-nederland-1948-2008-vraag22.png$$, $$Gebruik bron 11. Een bewering: Dit artikel van De Gelderlander geeft een eenzijdig beeld van de gebeurtenissen rondom het verbod op de vertoning van de film Rock around the clock. 3p 22 Licht deze bewering toe door aan te geven:
− waaruit de eenzijdigheid blijkt, waarbij je je antwoord ondersteunt met een verwijzing naar de bron en
− met welke verandering in de Nederlandse samenleving de redactie van de krant moeite heeft.$$, array['061623d0-bbcd-473e-915b-02773c969050']::uuid[]),
  ('faad6655-fc1b-42ea-a50a-1bdd09d5bc44', 'ca0453ec-9481-495e-9226-2dc44d098d8d', 25,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["moedermavo", "tweede feministische golf", "maakbare samenleving", "kabinet-Den Uyl", "positie van vrouwen", "argumenteren"]'::jsonb,
   $$Ondersteunen dat de financiering van moedermavo's paste bij de veranderende positie van vrouwen en het ideaal van de maakbare samenleving.$$,
   $$geschiedenis-havo-2021-ii-nederland-1948-2008-vraag25.png$$, $$In de jaren 1970 werden in Nederland zogenoemde ''moedermavo''s'' opgericht. Op deze scholen konden volwassenen op latere leeftijd alsnog een middelbareschooldiploma halen. Het kabinet- Den Uyl (1973-1977) besloot deze scholen financieel te ondersteunen. Twee beweringen: De financiering van deze moedermavo''s:
1 ondersteunde de veranderende positie van vrouwen in de samenleving.
2 paste bij het ideaal van een maakbare samenleving in die tijd. 2p 25 Ondersteun beide beweringen met een argument.$$, array[]::uuid[]),
  ('9248644c-cc11-4efb-850b-e40b58d581c2', 'ce33ec88-13f7-4844-ba63-e4d2a538dc57', 23,
   '[{"domain": "Nederland (1948-2008)", "subdomain": "Veranderende maatschappelijke verhoudingen (1948-1978)"}]'::jsonb,
   '["consumptiemaatschappij", "welvaartsgroei", "supermarkt", "jaren 1960", "verband uitleggen", "economische groei"]'::jsonb,
   $$Uitleggen dat een wedstrijd voor caissières in 1962 paste bij de opkomst van de consumptiemaatschappij.$$,
   $$geschiedenis-havo-2021-ii-computer-en-televisie-vraag23.png$$, $$In 1962 organiseerde een supermarktketen een wedstrijd voor caissières, waarbij de deelneemsters werden beoordeeld op nauwkeurigheid en snelheid. Deze wedstrijd paste bij de opkomst van de consumptiemaatschappij. 2p 23 Leg dit verband uit.$$, array[]::uuid[]);
